const incoming = $input.item.json || {};
const b = (incoming.body && typeof incoming.body === "object") ? incoming.body : incoming;
const required = ["tenant_id","delivery_request_id","recovery_id","opportunity_id","intervention_id","to","subject","idempotency_key","correlation_id"];
const missing = required.filter(k => b[k] === undefined || b[k] === null || String(b[k]).trim() === "");
const channel = String(b.channel || "").toUpperCase();
const hasBody = (b.html_body && String(b.html_body).trim() !== "") || (b.text_body && String(b.text_body).trim() !== "");
let precheck_ok = true;
let precheck_error = null;
if (missing.length > 0) { precheck_ok = false; precheck_error = "MISSING_FIELDS:" + missing.join(","); }
else if (channel !== "EMAIL") { precheck_ok = false; precheck_error = "UNSUPPORTED_CHANNEL"; }
else if (!hasBody) { precheck_ok = false; precheck_error = "MISSING_CONTENT"; }
return {
  precheck_ok,
  precheck_error,
  tenant_id: b.tenant_id || null,
  delivery_request_id: b.delivery_request_id || null,
  message_id: b.message_id || null,
  recovery_id: b.recovery_id || null,
  opportunity_id: b.opportunity_id || null,
  intervention_id: b.intervention_id || null,
  channel: channel || null,
  to: b.to || null,
  subject: b.subject || null,
  html_body: b.html_body || null,
  text_body: b.text_body || null,
  tracking_token: b.tracking_token || null,
  correlation_id: b.correlation_id || null,
  idempotency_key: b.idempotency_key || null,
  metadata: b.metadata || {},
};

const v = $("Validate & Normalize").item.json;
let auth = null; try { auth = $("Authorize & Context").item.json; } catch (e) { auth = null; }
let send = null; try { send = $("MailerSend Send").item.json; } catch (e) { send = null; }
const authBody = auth && auth.body && !Array.isArray(auth.body) ? auth.body : {};
const authStatus = auth ? auth.statusCode : null;
const authorized = v.precheck_ok === true && authStatus >= 200 && authStatus < 300 && authBody.can_send === true;

let state = "REJECTED";
let errorClass = null;
let retryable = false;
let http_status = 422;
let provider_message_id = null;
let provider_status_code = null;
let provider_response = {};

if (v.precheck_ok !== true) {
  state = "REJECTED"; errorClass = v.precheck_error || "VALIDATION"; http_status = 422;
} else if (!(authStatus >= 200 && authStatus < 300)) {
  state = "UNKNOWN"; errorClass = "AUTH_CONTEXT_ERROR"; retryable = true; http_status = 502;
} else if (authBody.can_send !== true) {
  const reason = String(authBody.reason || "NOT_AUTHORIZED").toUpperCase();
  state = "REJECTED"; errorClass = reason; http_status = 409;
  provider_response = { authorization_reason: reason };
} else if (!send || send.statusCode === undefined || send.statusCode === null) {
  state = "UNKNOWN"; errorClass = "AMBIGUOUS_TRANSPORT"; retryable = true; http_status = 502;
} else {
  const sc = Number(send.statusCode); provider_status_code = sc;
  provider_response = send.body || {};
  const headers = send.headers || {};
  if (sc >= 200 && sc < 300) {
    state = "ACCEPTED"; http_status = 202;
    provider_message_id = headers["x-message-id"] || (send.body && send.body.message_id) || null;
  } else if (sc === 401 || sc === 403) {
    state = "FAILED"; errorClass = "PROVIDER_AUTH"; http_status = 502;
  } else if (sc === 429) {
    state = "UNKNOWN"; errorClass = "RATE_LIMITED"; retryable = true; http_status = 429;
  } else if (sc >= 400 && sc < 500) {
    state = "FAILED"; errorClass = "PROVIDER_VALIDATION"; http_status = 502;
  } else if (sc >= 500) {
    state = "UNKNOWN"; errorClass = "PROVIDER_TRANSIENT"; retryable = true; http_status = 502;
  } else {
    state = "UNKNOWN"; errorClass = "AMBIGUOUS_TRANSPORT"; retryable = true; http_status = 502;
  }
}
return {
  tenant_id: v.tenant_id,
  delivery_request_id: authorized ? authBody.delivery_request_id : null,
  intervention_id: v.intervention_id,
  recovery_id: v.recovery_id,
  opportunity_id: v.opportunity_id,
  correlation_id: v.correlation_id,
  provider: authBody.provider || "mailersend",
  provider_message_id,
  provider_status_code,
  state,
  error_class: errorClass,
  failure_category: errorClass,
  retryable,
  should_record_result: authorized,
  provider_response,
  http_status
};

const headers = $json.headers || {};
const payload = $json.body || {};
const signatureEntry = Object.entries(headers).find(([key]) => key.toLowerCase() === "signature");
const signature = signatureEntry ? signatureEntry[1] : null;
const raw = ($input.item.binary && $input.item.binary.data && $input.item.binary.data.data) ? $input.item.binary.data.data : null;
return { signature, raw_body_base64: raw, payload, is_test: payload.type === "webhook.test", valid_shape: !!raw && !!payload && typeof payload === "object" && typeof payload.type === "string" };

const headers = $json.headers || {};
const payload = $json.body || {};
const signatureEntry = Object.entries(headers).find(([key]) => key.toLowerCase() === "signature");
const signature = signatureEntry ? signatureEntry[1] : null;
const raw = ($input.item.binary && $input.item.binary.data && $input.item.binary.data.data) ? $input.item.binary.data.data : null;
return { signature, raw_body_base64: raw, payload, is_test: payload.type === "webhook.test", valid_shape: !!raw && !!payload && typeof payload === "object" && typeof payload.type === "string" };

const c = $("Classify Result").item.json || {};
return { json: {
  statusCode: Number(c.http_status || 500),
  body: {
    status: c.state === "ACCEPTED" ? "accepted" : "not_sent",
    state: c.state || "UNKNOWN",
    failure_category: c.failure_category || null,
    delivery_request_id: c.delivery_request_id || null,
    provider_message_id: c.provider_message_id || null,
    correlation_id: c.correlation_id || null
  }
} };

const p = $('Prepare One-Off Test Delivery').item.json.body || {};
const r = $input.item.json || {};
const sc = Number(r.statusCode || 0);
const state = sc >= 200 && sc < 300 ? 'ACCEPTED' : (sc === 0 || sc >= 500 ? 'UNKNOWN' : 'FAILED');
return { tenant_id:p.tenant_id, delivery_request_id:p.delivery_request_id, intervention_id:p.intervention_id, recovery_id:p.recovery_id, opportunity_id:p.opportunity_id, correlation_id:p.correlation_id, provider:'mailersend', provider_message_id:(r.headers && r.headers['x-message-id']) || (r.body && r.body.message_id) || null, provider_status_code:sc || null, state, error_class:state === 'ACCEPTED' ? null : (r.body && r.body.error) || 'ONE_OFF_PROVIDER_FAILURE', retryable:state === 'UNKNOWN', provider_response:r.body || {}, test_only:true };

const c = $('Classify One-Off Provider Result').item.json || {};
const rec = $input.item.json || {};
return { status:c.state === 'ACCEPTED' ? 'accepted_by_mailersend' : 'not_accepted', provider:'MailerSend', provider_status_code:c.provider_status_code, provider_message_id:c.provider_message_id, recipient:'[REDACTED_EMAIL]', subject:"Your checkout, whenever you're ready", delivery_request_id:c.delivery_request_id, recorded:rec.statusCode >= 200 && rec.statusCode < 300, note:c.state === 'ACCEPTED' ? 'MailerSend accepted the message; inbox delivery is not yet confirmed.' : 'The provider did not accept the message.' };

const r = $input.item.json || {};
const b = r.body || {};
return { status:'not_sent', reason:b.reason || 'ONE_OFF_TEST_AUTHORIZATION_FAILED', provider_called:false, http_status:r.statusCode || null };
